CREATE TABLE IF NOT EXISTS finance_wallet_accounts(tenant_id uuid NOT NULL,owner_id uuid NOT NULL,bucket text NOT NULL CHECK(bucket IN('cash','refund','commission','promo')),balance numeric(24,0) NOT NULL DEFAULT 0 CHECK(balance>=0),reserved numeric(24,0) NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=balance),PRIMARY KEY(tenant_id,owner_id,bucket));
CREATE TABLE IF NOT EXISTS finance_resources(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,owner_id uuid NOT NULL,kind text NOT NULL,state text NOT NULL,version integer NOT NULL DEFAULT 1 CHECK(version>0),data jsonb NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS finance_resource_scope ON finance_resources(tenant_id,owner_id,kind,id);
CREATE TABLE IF NOT EXISTS finance_commands(tenant_id uuid NOT NULL,actor_id uuid NOT NULL,operation text NOT NULL,key text NOT NULL,digest text NOT NULL,response jsonb NOT NULL,PRIMARY KEY(tenant_id,actor_id,operation,key));
CREATE TABLE IF NOT EXISTS finance_receipts(provider text NOT NULL,reference text NOT NULL,tenant_id uuid NOT NULL,owner_id uuid NOT NULL,purpose text NOT NULL,amount numeric(24,0) NOT NULL CHECK(amount>0),target_reference text,digest text NOT NULL,resource_id uuid NOT NULL REFERENCES finance_resources(id),created_at timestamptz NOT NULL,PRIMARY KEY(provider,reference));
CREATE TABLE IF NOT EXISTS finance_unique_sources(kind text NOT NULL,reference text NOT NULL,resource_id uuid NOT NULL REFERENCES finance_resources(id),PRIMARY KEY(kind,reference));
CREATE TABLE IF NOT EXISTS finance_outbox(id uuid PRIMARY KEY,event_type text NOT NULL,resource_id uuid NOT NULL,version integer NOT NULL,payload jsonb NOT NULL,state text NOT NULL DEFAULT 'pending' CHECK(state IN('pending','delivered','dead')),created_at timestamptz NOT NULL,UNIQUE(resource_id,version,event_type));
CREATE TABLE IF NOT EXISTS finance_audit(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,actor_id uuid NOT NULL,operation text NOT NULL,resource_id uuid NOT NULL,reason text,created_at timestamptz NOT NULL);
